`,"../sketches/sketch-3.js":`// Circle launched from a mouse press
let circleX = null;
let circleY = null;

function setup() {
  createCanvas(640, 360);
}

function draw() {
  background(20);
  noFill();
  stroke(255);
  // update circle
  if (circleX !== null) {
    circleX = circleX + 5;
  }
  // clear circle
  if (circleX > width) {
    circleX = null;
  }
  // draw circle
  if (circleX !== null) {
    circle(circleX, circleY, 133);
  }
}

function mousePressed() {
  circleX = mouseX;
  circleY = mouseY;
}
`,"../sketches/sketch-4.js":`// Circles launched from mouse presses, stored in an array
let circles = [];

function setup() {
  createCanvas(640, 360);
}

function draw() {
  background(20);
  noFill();
  stroke(255);
  // update circles
  for (let i = 0; i < circles.length; i++) {
    circles[i].x = circles[i].x + 5;
  }
  // clear circles
  // loop backwards so removing a circle doesn't skip the next one
  for (let i = circles.length - 1; i >= 0; i--) {
    if (circles[i].x > width) {
      circles.splice(i, 1);
    }
  }
  // draw circles
  for (let i = 0; i < circles.length; i++) {
    circle(circles[i].x, circles[i].y, 133);
  }
}

function mousePressed() {
  circles.push({ x: mouseX, y: mouseY });
}
